-- Independent state surface. Operator owns capture; Agent has two read-only tools.
INSTALL ossie FROM community;
LOAD ossie;
INSTALL duckdb_mcp FROM community;
LOAD duckdb_mcp;
-- BEGIN OPERATOR SETUP
CREATE TABLE observations(observation_id VARCHAR, user_id VARCHAR, ds DATE,
                          product VARCHAR, amount_usd DECIMAL(18,2), classification_value INTEGER);
COPY observations FROM 'docs/research/ossie-req-001/multi-period-research/every-day/observations.csv' (HEADER);
CALL ossie_bundle_load('test/fixtures/population-observation/bundle-10.json');
-- END OPERATOR SETUP
PRAGMA mcp_publish_query('SELECT * FROM ossie_concepts_v2()', 'ossie://population/concepts', 'json', 0);
PRAGMA mcp_publish_query('SELECT * FROM ossie_population_capabilities()', 'ossie://population/capabilities', 'json', 0);
PRAGMA mcp_publish_query('SELECT * FROM ossie_daily_states_program()', 'ossie://population/state-program', 'json', 0);
PRAGMA mcp_publish_query(
 'SELECT ''ossie-daily-state-mcp-surface-v1'' AS schema_version, ''["population_daily_states","population_daily_states_compile"]'' AS tools_json, false AS reload_tool, false AS arbitrary_sql_tool, ''scope only inside request_json; unknown outer arguments ignored; upstream may coerce objects; clients send Strings'' AS argument_boundary',
 'ossie://population/state-surface','json',0
);
PRAGMA mcp_publish_tool(
 'population_daily_states',
 'request_json is a String containing exactly one JSON object, not an object argument or double-encoded JSON string. Inner shape is exactly {"start_date":S,"end_date":E,"products":P,"user_domain":"captured_users","transitions":"within_request_days"}. S/E are String canonical Gregorian YYYY-MM-DD dates in years0001..9999; start<=end, both inclusive,1..366 natural days. No BC, wide years or infinity. P is exactly {"mode":"all"} or {"mode":"subset","values":[string,...]}; subset has1..64 unique nonempty raw UTF-8 strings, each decoded value <=256 bytes. Preserve case, Unicode and control characters via JSON escaping; no trim, case fold or normalization. This Agent requires subset values already ascending by raw UTF-8 bytes; native accepts arbitrary order and sorts subset order while preserving each decoded string. Exact fields, no missing/default/unknown/duplicate keys or null/number/boolean values; original inner JSON <=16384 UTF-8 bytes including whitespace/escaping. concept is a separate outer String: use the actual qualification_concept discovered from state-program, not User or root observation concept. Both query and compile use this identical request grammar. Date bounds define the emitted calendar and contributing observations; products filter contributing observations. Neither narrows the User domain, which remains all distinct Users of the full frozen capture. Any TRUE wins; nonempty all FALSE is FALSE; missing/all NULL/FALSE+NULL is UNKNOWN, with no carry. On query execution, return every User/day and every within-request adjacent natural-day comparison, including unchanged; changed means different state labels, including changes involving UNKNOWN. Totals count User/day, changed counts User/adjacent-day pairs, not unique changed Users or observation rows. Combined states+comparisons <=10000, full internal JSON <=1048576 bytes including metadata/escaping, refusal without paging/truncation. Query executes/computes; compile binds/explains without computing execution states/comparisons/counts; both tools enforce the metadata-based captured_User_count*(2*days-1)<=10000 gate at binding. Dedicated state contract takes precedence over generic sparse-observation descriptions. Unknown outer arguments are ignored; upstream may coerce values; clients send Strings. This Agent sends exactly concept and request_json Strings. Read-only state tools, no import/reload/arbitrary SQL or historical-rule inference. Generic syntax example: Assumed other frozen daily-observation program declares this exact qualification concept/rule. Current pilot does not declare it; do not execute these outer parameters against pilot. No input rows, state outputs, counts or answers supplied. These arguments are not executable against the current pilot. Inner object: {"start_date":"2031-04-05","end_date":"2031-04-07","products":{"mode":"subset","values":["Catalog-A","catalog-a","商品"]},"user_domain":"captured_users","transitions":"within_request_days"} Serialized outer arguments: {"concept":"EligibleVisit","request_json":"{\"start_date\":\"2031-04-05\",\"end_date\":\"2031-04-07\",\"products\":{\"mode\":\"subset\",\"values\":[\"Catalog-A\",\"catalog-a\",\"商品\"]},\"user_domain\":\"captured_users\",\"transitions\":\"within_request_days\"}"}. Query carrier result_json is ossie-daily-states-result-v1, state_api_version1.0.0, executed=true. Counts are integer text. Return complete states/comparisons and totals; compare actual current frozen rule, request and six snapshot hashes with state-program.',
 'SELECT * FROM ossie_daily_states_json($concept,$request_json)',
 '{"concept":{"type":"string"},"request_json":{"type":"string"}}',
 '["concept","request_json"]','json'
);
